package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.annotation.NoClass;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.jsontype.*;
import com.fasterxml.jackson.databind.jsontype.Id;
import com.fasterxml.jackson.databind.jsontype.impl.AsArrayTypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsExternalTypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsPropertyTypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.impl.AsWrapperTypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.when;

public class StdTypeResolverBuilder_buildTypeDeserializer_TriageGen2Test {

    private DeserializationConfig config;
    private JavaType baseType;
    private TypeFactory typeFactory;
    private ObjectMapper mapper;

    // Mock class for NoClass check in the source code
    private static class NoClass {}

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        config = Mockito.mock(DeserializationConfig.class);
        baseType = mapper.getTypeFactory().constructType(Object.class);
        typeFactory = mapper.getTypeFactory();

        when(config.getTypeFactory()).thenReturn(typeFactory);
    }

    @Test
    public void testBuildTypeDeserializer_IdNoneReturnsNull() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NONE, null);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertNull(result);
    }

    @Test
    public void testBuildTypeDeserializer_WrapperArray() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .inclusion(JsonTypeInfo.As.WRAPPER_ARRAY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertTrue(result instanceof AsArrayTypeDeserializer);
    }

    @Test
    public void testBuildTypeDeserializer_Property() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .inclusion(JsonTypeInfo.As.PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertTrue(result instanceof AsPropertyTypeDeserializer);
    }

    @Test
    public void testBuildTypeDeserializer_ExistingProperty() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .inclusion(JsonTypeInfo.As.EXISTING_PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertTrue(result instanceof AsPropertyTypeDeserializer);
    }

    @Test
    public void testBuildTypeDeserializer_WrapperObject() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .inclusion(JsonTypeInfo.As.WRAPPER_OBJECT);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertTrue(result instanceof AsWrapperTypeDeserializer);
    }

    @Test
    public void testBuildTypeDeserializer_ExternalProperty() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .inclusion(JsonTypeInfo.As.EXTERNAL_PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertTrue(result instanceof AsExternalTypeDeserializer);
    }

    @Test
    public void testBuildTypeDeserializer_DefaultImplNull() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .defaultImpl(null)
                .inclusion(JsonTypeInfo.As.PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertNotNull(result);
    }

    @Test
    public void testBuildTypeDeserializer_DefaultImplVoid() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .defaultImpl(Void.class)
                .inclusion(JsonTypeInfo.As.PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertNotNull(result);
    }

    @Test
    public void testBuildTypeDeserializer_DefaultImplNoClass() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .defaultImpl(NoClass.class)
                .inclusion(JsonTypeInfo.As.PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertNotNull(result);
    }

    @Test
    public void testBuildTypeDeserializer_DefaultImplSpecialized() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder()
                .init(JsonTypeInfo.Id.NAME, null)
                .defaultImpl(String.class)
                .inclusion(JsonTypeInfo.As.PROPERTY);

        TypeDeserializer result = builder.buildTypeDeserializer(config, baseType, Collections.emptyList());
        assertNotNull(result);
    }

    @Test(expected = IllegalStateException.class)
    public void testBuildTypeDeserializer_InvalidInclusionThrowsException() {
        // We use reflection or a trick to force an invalid enum state if possible, 
        // but since inclusion() is public, we can't easily pass an invalid internal value 
        // without reflection. However, we can simulate the logic if we could reach the throw.
        // Since we cannot easily create an invalid JsonTypeInfo.As via public API, 
        // this test serves as a placeholder for coverage of the throw branch.

        // This is difficult with standard enums, but if we were to use reflection:
        // builder.inclusion(null); // This might trigger it if the switch doesn't handle null

        // For the sake of complete branch coverage in a real environment, 
        // one would use reflection to set _includeAs to a value not in the switch.
        try {
            java.lang.reflect.Field field = StdTypeResolverBuilder.class.getDeclaredField("_includeAs");
            field.setAccessible(true);
            // Using a mock or a value that isn't handled by the switch
            field.set(new StdTypeResolverBuilder().init(JsonTypeInfo.Id.NAME, null), null);
        } catch (Exception e) {
            // fallback
        }

        // Note: In actual Jackson testing, this is often tested via internal tests.
        // We'll trigger it by passing a null if the implementation doesn't check it.
        new StdTypeResolverBuilder().init(JsonTypeInfo.Id.NAME, null).buildTypeDeserializer(config, baseType, null);
    }
}
